/**
 * Frozen Documentation Imports acceptance data before delegating to Gate 3.
 * Expected occurrences are authored explicitly, never regenerated by either
 * checker. Alias migrations and replacement suggestions have separate tests.
 */
const file = 'docs/en/guide/inclusion/foldable-devices.mdx';
const source = '../../../../src/components/example';
const occurrence = (line, specifier = source) => ({ file, line, specifier });

export const documentationBoundaryFixtures = [
  {
    name: 'multiline static import',
    file,
    content: `import {
  Example,
} from '${source}';`,
    expected: [occurrence(1)],
  },
  {
    name: 'side effects and unknown runtime roots',
    file,
    content:
      "import '../../../../src/styles.css';\nimport Theme from '../../../../theme/index';",
    expected: [
      occurrence(1, '../../../../src/styles.css'),
      occurrence(2, '../../../../theme/index'),
    ],
  },
  {
    name: 'shared aliases and document-local relatives',
    file,
    content: "import X from '@lynx/example';\nimport Local from './Example';",
    expected: [],
  },
  {
    name: 'fenced examples and containers',
    file,
    content: [
      '~~~tsx',
      `import X from '${source}';`,
      '~~~',
      '',
      '```tsx',
      `import X from '${source}';`,
      '```',
      '',
      '> ````tsx',
      `> import('${source}');`,
      '> ````',
    ].join('\n'),
    expected: [],
  },
  {
    name: 'unclosed blockquote fence ends at container boundary',
    file,
    content: [
      '> ```tsx',
      `> import('${source}');`,
      `import X from '${source}';`,
    ].join('\n'),
    expected: [occurrence(3)],
  },
  {
    name: 'unclosed list fence ends at container boundary',
    file,
    content: [
      '- Example:',
      '',
      '  ```js',
      `  import('${source}')`,
      '',
      `import X from '${source}'`,
    ].join('\n'),
    expected: [occurrence(6)],
  },
  {
    name: 'dynamic literal and no-substitution template',
    file,
    content: `export const load = () =>\n  import('${source}');\nexport const template = () => import(\`${source}\`);`,
    expected: [occurrence(2), occurrence(3)],
  },
  {
    name: 'comments between executable tokens',
    file,
    content: [
      `import X from/* owner */'${source}';`,
      `export { X } from/* owner */'${source}';`,
      `import/* styles */'${source}';`,
      `export const lazy = import/* lazy */(/* source */'${source}'/* end */);`,
    ].join('\n'),
    expected: [1, 2, 3, 4].map((line) => occurrence(line)),
  },
  {
    name: 'leading comment followed by import-like prose',
    file,
    content: `/* ownership */ import X from '${source}';`,
    expected: [],
  },
  {
    name: 'JavaScript comments are not imports',
    file,
    content: `// import('${source}');\n{/*\nimport X from '${source}';\n*/}`,
    expected: [],
  },
  {
    name: 'strings prose and inline code are not imports',
    file,
    content: [
      `export const example = "import('${source}')";`,
      '',
      `Use \`import('${source}')\` to load a module.`,
      `Use \`\`import('${source}')\`\` too.`,
      `Use \`\` \`\`\` import('${source}') \`\` here.`,
    ].join('\n'),
    expected: [],
  },
  {
    name: 'semicolonless imports do not absorb prose or exported strings',
    file,
    content: [
      "import External from '@scope/components'",
      '',
      `The prose says from '${source}'.`,
      '',
      `export const example = "} from '${source}'";`,
    ].join('\n'),
    expected: [],
  },
  {
    name: 'consecutive semicolonless imports retain their lines',
    file,
    content: `import External from '@scope/components'\nimport Local from '${source}'`,
    expected: [occurrence(2)],
  },
  {
    name: 'preceding blank lines retain import locations',
    file,
    content: `\n\nimport X from '${source}';`,
    expected: [occurrence(3)],
  },
  {
    name: 'URL expressions and template substitutions are executable',
    file,
    content: `https://example.com {import('${source}')}\n\nexport const value = \`text \${import('${source}')}\``,
    expected: [occurrence(1), occurrence(3)],
  },
  {
    name: 'Unicode identifiers',
    file,
    content: `import 示例 from '${source}'`,
    expected: [occurrence(1)],
  },
  ...['\n', '\r\n'].map((newline) => ({
    name: `frontmatter and heading IDs (${JSON.stringify(newline)})`,
    file,
    content: [
      '---',
      `title: "import ignored from ${source}"`,
      '---',
      '',
      '# Example {#custom}',
      '',
      `import X from '${source}'`,
    ].join(newline),
    expected: [occurrence(7)],
  })),
  {
    name: 'JSX attributes spreads and GFM table cells',
    file,
    content: [
      `<Example load={() => import('${source}')} {...{load: import('${source}')}} />`,
      '',
      '| Example |',
      '| --- |',
      `| {import('${source}')} |`,
    ].join('\n'),
    expected: [occurrence(1), occurrence(1), occurrence(5)],
  },
  {
    name: 're-exports and decoded strings without executing source',
    file,
    content: [
      `export * from '${source}'`,
      `export * as group from '${source}'`,
      "import X from '\\u002e\\u002e/../../../src/components/example'",
      "export const crash = (() => { throw new Error('must not execute'); })()",
    ].join('\n'),
    expected: [occurrence(1), occurrence(2), occurrence(3)],
  },
  {
    name: 'plain Markdown has no executable imports',
    file: file.replace('.mdx', '.md'),
    content: `import X from '${source}'`,
    expected: [],
  },
  {
    name: 'shared documentation has the same boundary',
    file: 'sharedDocs/packageDocs/example.mdx',
    content: "import X from '../../src/components/example'",
    expected: [
      {
        file: 'sharedDocs/packageDocs/example.mdx',
        line: 1,
        specifier: '../../src/components/example',
      },
    ],
  },
  {
    name: 'computed dynamic sources are not evaluated',
    file,
    content: [
      "import X from '@lynx/index'",
      "export const load = (name) => import('../../../../src/' + name)",
      'export const template = (name) => import(`../../../../src/components/${name}`)',
      "export const local = () => import('./Example')",
    ].join('\n'),
    expected: [],
  },
  {
    name: 'JavaScript frontmatter is never evaluated',
    file,
    content: [
      '---javascript',
      "(() => { throw new Error('must not execute'); })()",
      '---',
      '',
      `import X from '${source}'`,
    ].join('\n'),
    expected: [occurrence(5)],
  },
  ...[
    '../../../../src',
    '../../../../theme',
    '../../../../src?raw',
    '../../../../theme#example',
    '../../../../src/components/missing.tsx?raw#example',
    '../../../../theme/missing.css?raw',
  ].map((specifier) => ({
    name: `missing target or directory root: ${specifier}`,
    file,
    content: `import X from '${specifier}'`,
    expected: [occurrence(1, specifier)],
  })),
];

export const invalidDocumentationFixtures = [
  {
    name: 'non-module statement in MDX ESM',
    file,
    content: "import X from './x'\nconst x = 1",
    line: 2,
  },
  {
    name: 'invalid import syntax',
    file,
    content: '\nimport { from "./x";',
    line: 2,
  },
  {
    name: 'unsupported static import attributes',
    file,
    content: `import X from '${source}' with { type: 'json' };`,
    line: 1,
  },
];
